      "weight": 0.26
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration (19.0%) and Asylum seekers (4.8%) as top issues, with EU relations also present (2.7%)",
      "weight": 0.22
    },
    {
      "foundation": "care",
      "basis": "NHS (14.2%) and social services concerns like Education (3.6%) and Pensions (2.6%)",
      "weight": 0.20
    },
    {
      "foundation": "proportionality",
      "basis": "Tax/spend mean 5.54 indicating a tilt toward tax cutting, with low salience for redistribution themes",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "Low but present concern for Poverty/living standards (1.1%), Social inequalities (0.4%), and Services-spending (2.0%)",
      "weight": 0.09
    },
    {
      "foundation": "sanctity",
      "basis": "Relatively low salience for Values, Morality (0.6%), Drugs (0.5%), and Environment (1.8%)",
      "weight": 0.05
    }
  ]
}

{
  "justification": "Issue salience is dominated by immigration, the NHS, and crime, alongside a social-attitudes mean that leans toward prioritizing crime over civil liberties, indicating strong pulls from authority, loyalty, and care operating in both expansive and restrictive directions. Near-centrist positions on EU integration and tax/spend, with smaller but present morality/drugs concerns, suggest moderate roles for equality, proportionality, and sanctity.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "High NHS salience (14.2%) and migration/asylum items (19.0%/4.8%) signal concern about suffering and welfare.",
      "weight": 0.21
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration (19.0%) and terrorism (5.8%), plus mid EU position (5.16/10), reflect group cohesion and national allegiance.",
      "weight": 0.17
    },
    {
      "foundation": "authority",
      "basis": "Law&order-crime salience (13.2%) and low social-liberty score (2.35/10) indicate preference for order and deference to authority.",
      "weight": 0.23
    },
    {
      "foundation": "sanctity",
      "basis": "Immigration/asylum and terrorism often invoke purity/contamination frames; 'Values, Morality' (0.6%) and Drugs (0.5%).",
