    },
    {
      "foundation": "equality",
      "basis": "NHS prominence and some services/spending concern (2.0%) point to equal access and treatment motives (social inequalities 0.4%).",
      "weight": 0.14
    },
    {
      "foundation": "proportionality",
      "basis": "Tax/spend mean (5.54/10) and emphasis on crime suggest fairness-as-desert—rewarding contribution and punishing offenders.",
      "weight": 0.16
    }
  ]
}

{
